import java.util.*;class Solution{public List<Integer> largestDivisibleSubset(int[]a){List<Integer>o=new ArrayList<>();if(a.length==0)return o;Arrays.sort(a);int n=a.length,b=0;int[]d=new int[n],p=new int[n];Arrays.fill(d,1);Arrays.fill(p,-1);for(int i=0;i<n;i++){for(int j=0;j<i;j++)if(a[i]%a[j]==0&&d[j]+1>d[i]){d[i]=d[j]+1;p[i]=j;}if(d[i]>d[b])b=i;}for(int i=b;i!=-1;i=p[i])o.add(a[i]);Collections.reverse(o);return o;}}
